typedef struct contract *contract_t;          /* contract.h: opaque handle */
contract_t contract_create(const char *customer, const char *supplier,
                           long start_epoch);              /* returns NULL if invalid */
void contract_destroy(contract_t c);

/* contract.c */
contract_t contract_create(const char *cust, const char *supp, long start) {
    if (!cust || !*cust || !supp || !*supp) return NULL; /* validate BEFORE alloc */
    contract_t c = malloc(sizeof *c);
    if (!c) return NULL;
    c->customer = strdup(cust);                         /* own copies: caller buffers */
    c->supplier = strdup(supp);                         /*   may die anytime */
    if (!c->customer || !c->supplier) { contract_destroy(c); return NULL; }
    c->start = start;
    return c;
}
